        "src/main/java/com/example/shortener/service/UrlValidator.java",
        "src/main/java/com/example/shortener/service/ShortCodeGenerator.java"
      ],
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC3",
        "AC4",
        "AC6",
        "AC7",
        "AC10",
        "AC11"
      ]
    },
    {
      "id": "T4",
      "title": "Expose creation and link-details HTTP APIs",
      "description": "Implement POST /api/links returning HTTP 201 and the requested JSON fields, and GET /api/links/{code} returning link metadata without changing the click count. Build shortUrl from the incoming request scheme, host, port, context path, and generated code. Add centralized JSON error handling with HTTP 400 for invalid creation input and HTTP 404 for unknown codes, including a non-empty error field.",
      "dependsOn": [
        "T3"
      ],
      "files": [
        "src/main/java/com/example/shortener/controller/LinkController.java",
