        "src/main/java/com/example/shortener/exception/LinkNotFoundException.java",
        "src/main/java/com/example/shortener/exception/ApiExceptionHandler.java"
      ],
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC4",
        "AC9",
        "AC10"
      ]
    },
    {
      "id": "T5",
      "title": "Implement the public redirect endpoint with atomic click tracking",
      "description": "Implement GET /{code} as a public redirect endpoint that resolves the code, atomically increments the persisted click count exactly once, and returns HTTP 302 with the original URL in the Location header. Ensure unknown codes return JSON-compatible HTTP 404 handling and that API routes are not captured incorrectly by the redirect mapping.",
      "dependsOn": [
        "T2",
        "T3",
        "T4"
      ],
      "files": [
        "src/main/java/com/example/shortener/controller/RedirectController.java",
        "src/main/java/com/example/shortener/service/LinkService.java",
        "src/main/java/com/example/shortener/repository/LinkRepository.java"
