    {
      "id": "T6",
      "title": "Add integration and concurrency coverage",
      "description": "Extend the test suite with MockMvc or equivalent HTTP integration tests covering successful creation, duplicate submissions, URL validation, code shape and uniqueness, redirects, unknown codes, details responses, short URL construction, persistence through the JPA repository, and concurrent redirects. Verify concurrent click increments equal the number of successful redirect responses.",
      "dependsOn": [
        "T4",
        "T5"
