      "files": [
        "src/test/java/com/example/shortener/UrlShortenerApplicationTests.java",
        "src/test/java/com/example/shortener/LinkApiIntegrationTests.java",
        "src/test/java/com/example/shortener/LinkConcurrencyTests.java"
      ],
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC3",
