  ],
  "risks": [
    {
      "risk": "Concurrent creations could generate the same random code or encounter a database unique-constraint race.",
      "mitigation": "Use a database unique constraint on code, generate with SecureRandom, catch duplicate-key failures, and retry within a bounded creation loop; return a controlled server error only if the retry budget is exhausted."
    },
    {
      "risk": "Read-modify-write click updates can lose increments under concurrent redirects.",
      "mitigation": "Use an atomic repository update such as click_count = click_count + 1 in a transactional operation and only issue the redirect after a successful update."
    },
    {
      "risk": "A broad /{code} mapping could intercept /api/links/{code} or produce inconsistent error formats.",
      "mitigation": "Define explicit API mappings and a separate redirect mapping with route precedence or path constraints, and cover route behavior with integration tests."
    },
    {
      "risk": "URL parsing may accept values that are syntactically absolute but violate the stated security and validation rules.",
      "mitigation": "Require a parsed absolute URI with an exact http or https scheme, reject user information and malformed input, and test blank, relative, unsupported-scheme, malformed, and valid edge-case URLs."
    },
    {
      "risk": "Short URLs may be incorrect behind a context path, non-default port, or forwarded request configuration.",
      "mitigation": "Construct the URL from the current request's scheme, host, port, and context path as specified, and test representative host and port headers without introducing a separate public URL secret."
    },
    {
      "risk": "Redirect clients may automatically follow the 302 and obscure verification of the redirect response.",
      "mitigation": "Configure HTTP tests not to follow redirects and assert both the exact 302 status and Location header."
    }
  ],
  "decisions": [
    {
      "title": "Use a persistent JPA entity and repository rather than an in-memory map",
      "rationale": "The service must store links through Spring Data JPA and support retrieval and redirects through the configured H2 database during the application run.",
      "alternatives": [
        "Use an in-memory concurrent map",
        "Use a non-JPA JDBC implementation"
      ]
    },
    {
      "title": "Use seven-character SecureRandom URL-safe codes",
      "rationale": "The specification requires exactly seven URL-safe characters and codes that are hard to guess and non-sequential.",
      "alternatives": [
        "Use sequential numeric IDs",
        "Use UUIDs with variable or longer output",
        "Use a deterministic hash of the original URL"
      ]
    },
    {
      "title": "Allow every creation request to create a separate link",
      "rationale": "Duplicate original URLs are explicitly allowed to produce new codes, so creation will not deduplicate by URL.",
      "alternatives": [
        "Return an existing link for duplicate URLs",
        "Reject duplicate original URLs"
      ]
    },
    {
      "title": "Use an atomic database increment for click counts",
      "rationale": "Concurrent redirect requests must increase the count exactly once per successful redirect without lost updates.",
      "alternatives": [
        "Load the entity, increment in Java, and save it",
        "Synchronize only within the application process"
      ]
    },
    {
      "title": "Return HTTP 302 for successful redirects",
      "rationale": "The approved requirement assumption specifies a temporary redirect with the original URL in the Location header.",
      "alternatives": [
        "Use HTTP 301",
        "Use HTTP 307"
      ]
    },
    {
      "title": "Construct shortUrl from the incoming HTTP request",
      "rationale": "The approved assumption requires the returned URL to use the request scheme, host, port, context path, and generated code without a separate public-base-url configuration.",
      "alternatives": [
        "Require a configured public base URL",
        "Return only the code and omit shortUrl"
      ]
    },
    {
      "title": "Use centralized JSON exception handling",
      "rationale": "Creation validation and unknown-code failures need consistent JSON responses containing a clear error field, while redirects remain HTTP redirect responses.",
      "alternatives": [
        "Return ad hoc error bodies from each controller method",
        "Use framework-default HTML error responses"
      ]
    }
  ]
}

{
  "designDoc": "# URL Shortener Design\n\n## Scope and architecture\n\nThe service is a single Spring Boot application under `com.example.shortener`, using constructor injection and the existing H2/JPA configuration. The request flow is:\n\n`HTTP controller -> service -> Spring Data JPA repository -> H2`\n\nComponents:\n\n- `LinkController`: accepts link creation and metadata requests, applies Bean Validation at the HTTP boundary, builds the returned short URL from the current request, and delegates to `LinkService`.\n- `RedirectController`: handles `GET /{code}`, resolves the code through `LinkService`, atomically increments the click count, and returns a 302 redirect.\n- `LinkService`: owns URL validation, link creation, metadata lookup, redirect resolution, collision retries, and domain exceptions.\n- `UrlValidator`: validates nonblank absolute HTTP(S) URLs, rejecting malformed, relative, unsupported-scheme, and user-information URLs.\n- `ShortCodeGenerator`: uses `SecureRandom` to generate exactly seven characters from the URL-safe alphanumeric alphabet.\n- `Link`: JPA entity containing the generated database ID, unique code, original URL, and click count.\n- `LinkRepository`: provides code lookup, persistence, and an atomic database increment operation.\n- `ApiExceptionHandler`: converts domain and request errors to RFC 7807 `ProblemDetail` responses and includes an `error` property containing a clear message.\n\nThe implementation uses `jakarta.persistence.*` and `jakarta.validation.*`. No external infrastructure, cache, or in-memory link store is used. H2 remains the persistence store; persistence across application restarts is not required.\n\n## HTTP request flows\n\n### Create\n\n1. `POST /api/links` receives `{ \"url\": \"...\" }`.\n2. Bean Validation rejects a missing or blank value before service execution.\n3. `UrlValidator` parses the value as a URI and requires an absolute `http` or `https` scheme, a valid host, and no user information.\n4. `ShortCodeGenerator` creates a seven-character code with `SecureRandom`.\n5. The service saves the entity with click count zero and a database-enforced unique code.\n6. A unique-code collision is caught and retried with a new code, up to a bounded retry limit.\n7. The controller returns HTTP 201 with the original URL, code, request-derived short URL, and zero click count.\n\n### Metadata lookup\n\n1. `GET /api/links/{code}` calls the service repository lookup.\n2. The service maps the entity to the response without changing click count.\n3. Missing codes raise `LinkNotFoundException`, handled as HTTP 404 JSON ProblemDetail.\n\n### Redirect\n\n1. `GET /{code}` is handled separately from `/api/links/{code}`; the API route is not captured by the redirect mapping.\n2. The service finds the entity and reads its destination URL.\n3. The repository executes an atomic `click_count = click_count + 1` update in a transaction.\n4. The redirect is returned only after the update succeeds, using HTTP 302 and a `Location` header equal to the original URL.\n5. A missing code raises `LinkNotFoundException` and returns HTTP 404 without a redirect.\n\nThe redirect mapping may constrain the variable to seven URL-safe characters for normal codes. Requests for malformed or non-seven-character path values must still result in a 404 response rather than a redirect.\n\n## API and response model\n\n`CreateLinkRequest` is a record with `@NotBlank String url`. `LinkResponse` is a record containing `code`, `url`, `shortUrl`, and `clickCount`. The `url` field is the original submitted URL, preserving the submitted string after validation.\n\nError responses use `ProblemDetail` with a suitable `Content-Type` and an additional `error` property. The `error` property is nonempty and is also used as the stable, simple client-facing message. Validation failures, malformed JSON, and invalid URLs are HTTP 400. Missing links are HTTP 404.\n\nThe short URL is constructed from the current servlet request scheme, server name, port when non-default, context path, and `/{code}`. It does not depend on an external public-base-URL setting. Forwarded-header trust is not introduced by this design; deployments that need proxy-aware URL generation must configure the servlet container appropriately.\n\n## Data model\n\nTable/entity `Link`:\n\n- `id`: generated `Long` primary key.\n- `code`: non-null, length seven, unique database column, URL-safe characters generated by the service.\n- `originalUrl`: non-null URL string column with sufficient length for accepted URLs.\n- `clickCount`: non-null `long` or `Long`, initialized to zero.\n\nThe database unique constraint on `code` is authoritative. Application-side random generation is not treated as sufficient for uniqueness.\n\nThe repository exposes:\n\n- `Optional<Link> findByCode(String code)`.\n- `Link saveAndFlush(Link link)` or equivalent persistence operation used during creation.\n- A modifying query equivalent to `UPDATE Link l SET l.clickCount = l.clickCount + 1 WHERE l.code = :code`, returning the affected-row count.\n\nThe increment query is executed transactionally and atomically in the database, so concurrent redirect requests cannot overwrite each other's increments. No read-modify-write update is permitted.\n\n## URL validation algorithm\n\n1. Reject null or blank input.\n2. Reject input containing whitespace that makes URI parsing invalid.\n3. Parse with `java.net.URI`; catch syntax errors.\n4. Require `isAbsolute()`.\n5. Require the scheme, case-insensitively, to be exactly `http` or `https`.\n6. Reject non-null `getUserInfo()`.\n7. Require a valid nonempty host/authority appropriate for HTTP(S); malformed ports and malformed authorities are rejected.\n8. Preserve valid paths, queries, fragments, ports, and supported internationalized host names.\n\nThe service does not perform DNS resolution, reachability checks, malware scanning, or destination fetching.\n\n## Short-code generation and collision handling\n\n`ShortCodeGenerator` uses one application-scoped `SecureRandom` and the alphabet `A-Z`, `a-z`, and `0-9`. It samples seven characters independently, producing exactly seven URL-safe characters without sequential or timestamp-derived values.\n\nCreation retries a bounded number of times, such as ten attempts. Each candidate save is isolated in its own `REQUIRES_NEW` transaction through a separate persistence component, so a uniqueness failure rolls back only that candidate and does not poison the transaction used by later attempts. `DataIntegrityViolationException` caused by the unique code constraint triggers another candidate. Exhausting the retry budget produces a controlled HTTP 500 response; this is not expected under normal collision probability.\n\n## Transactions, concurrency, and reliability\n\n- Creation uses a transaction for each candidate insert and flushes before reporting success, ensuring the response is not returned before persistence succeeds.\n- Metadata lookup is read-only and does not increment clicks.\n- Redirect resolution is transactional. It first verifies the code, performs the atomic increment, and returns the destination only after the update affects one row.\n- The update query is the concurrency control mechanism; no Java synchronization or process-local lock is used.\n- The unique database constraint protects against concurrent creation requests and random collisions.\n- H2's in-memory database is retained with the existing `DB_CLOSE_DELAY=-1` configuration. A restart may clear data as explicitly permitted.\n- There is no external queue, cache, distributed lock, or retry infrastructure.\n\n## Routing and backward compatibility\n\nThis is a greenfield service, so there are no existing public endpoints to preserve. API routes are explicitly `/api/links` and `/api/links/{code}`. The redirect route is `/{code}` and is defined separately so nested API paths are not treated as redirect codes. Existing application bootstrap and H2 configuration remain unchanged.\n\n## Rejected alternatives\n\n- Read-modify-write click updates were rejected because concurrent redirects could lose increments.\n- UUID strings were rejected because their normal representation is longer than the required approximately seven-character code.\n- Sequential IDs, timestamps, hashes of the original URL, and ordinary `Random` were rejected because they are predictable or can expose URL-derived information.\n- Global deduplication by original URL was rejected because duplicate submissions are explicitly allowed to create separate links.\n- An in-memory `ConcurrentHashMap` was rejected because the requirement requires JPA/H2 persistence during the application run.\n- A configurable public base URL was rejected because the specified behavior derives the short URL from the incoming request and no such configuration is required.\n- HTTP 301/307/308 were rejected in favor of the approved 302 Found behavior.\n- Returning an ordinary custom JSON error object without `ProblemDetail` was rejected because the service must provide RFC 7807-style errors; the additional `error` property preserves the required simple client-facing field.",
  "apiContract": [
    {
      "method": "POST",
      "path": "/api/links",
      "request": {
        "url": "string; required, nonblank, absolute HTTP or HTTPS URL, without user information"
      },
      "responses": [
        {
          "status": 201,
          "body": {
            "code": "string; exactly 7 URL-safe characters",
            "url": "string; submitted original URL",
            "shortUrl": "string; request-derived URL ending in /{code}",
            "clickCount": 0
          }
        }
      ],
      "errors": [
        {
          "status": 400,
          "when": "The request body is missing, malformed, missing url, blank, relative, malformed, uses a non-http(s) scheme, has an invalid host/port, or contains user information. Body is RFC 7807 ProblemDetail with a nonempty error property."
        },
        {
          "status": 500,
          "when": "The bounded short-code collision retry budget is exhausted or an unexpected persistence failure occurs."
        }
      ]
    },
    {
      "method": "GET",
      "path": "/api/links/{code}",
      "request": null,
      "responses": [
        {
          "status": 200,
          "body": {
            "code": "string; stored seven-character code",
            "url": "string; original URL",
            "shortUrl": "string; request-derived URL for the code",
            "clickCount": "integer; current persisted count"
          }
        }
      ],
      "errors": [
        {
          "status": 404,
          "when": "No link exists for the supplied code. Body is RFC 7807 ProblemDetail with a nonempty error property."
        }
      ]
    },
    {
      "method": "GET",
      "path": "/{code}",
      "request": null,
      "responses": [
        {
          "status": 302,
          "body": null
        }
      ],
      "errors": [
        {
          "status": 404,
          "when": "The code does not exist or is not a valid seven-character redirect path. No Location header is issued; the response is JSON RFC 7807 ProblemDetail where the route is handled by the application."
        }
      ]
    }
