  "decisions": [
    {
      "title": "Use explicit API and redirect routes",
      "rationale": "Separating `/api/links` routes from `/{code}` prevents API requests from being interpreted as redirect requests while keeping the public redirect URL short.",
      "alternatives": [
        "Use a `/r/{code}` redirect prefix, rejected because the required public endpoint is `/{code}`.",
        "Use one controller with conditional routing, rejected because explicit Spring mappings are clearer and less error-prone."
      ]
    },
    {
      "title": "Use seven-character alphanumeric codes",
      "rationale": "The alphabet is URL-safe, produces exactly the required length, and avoids URL encoding concerns.",
      "alternatives": [
        "Use URL-safe Base64 with punctuation, rejected because the exact alphabet and padding behavior complicate path handling.",
        "Use UUIDs, rejected because they are too long.",
        "Use sequential numeric IDs, rejected because they are predictable."
      ]
    },
    {
      "title": "Use SecureRandom",
      "rationale": "Cryptographically strong random generation makes codes harder to guess and avoids predictable sequences.",
      "alternatives": [
        "Use java.util.Random, rejected because it is predictable.",
        "Derive codes from the original URL, rejected because codes could leak URL information and repeated URLs would naturally collide."
      ]
    },
    {
      "title": "Enforce uniqueness in both application and database",
      "rationale": "Retries handle ordinary random collisions, while the unique database constraint remains safe under concurrent requests.",
      "alternatives": [
        "Check existence before insert only, rejected because the check and insert are race-prone.",
        "Use synchronized creation, rejected because it is process-local and unnecessarily limits concurrency."
      ]
    },
    {
      "title": "Use an atomic database increment",
      "rationale": "An update expression incrementing the stored value prevents lost clicks under concurrent redirects.",
      "alternatives": [
        "Load, increment, and save the entity, rejected because concurrent transactions can overwrite increments.",
        "Use an in-memory counter and periodically persist, rejected because it is not durable for the application run and can lose counts."
      ]
    },
    {
      "title": "Isolate each code-insertion retry in a new transaction",
      "rationale": "A uniqueness violation can mark a transaction rollback-only. A separate transaction per candidate allows subsequent retries to execute reliably.",
      "alternatives": [
        "Retry inside one transaction, rejected because failed flushes may poison the transaction.",
        "Use a database sequence as the code, rejected because generated identifiers are predictable and not sufficiently hard to guess."
      ]
    },
    {
      "title": "Return 302 Found for redirects",
      "rationale": "This matches the approved requirement and is appropriate for a temporary-style redirect without caching semantics stronger than requested.",
      "alternatives": [
        "Use 301 or 308, rejected because those imply permanent redirect behavior.",
        "Use 307, rejected because the specified contract calls for 302."
      ]
    },
    {
