import com.example.shortener.exception.InvalidUrlException;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;

@Component
public class UrlValidator {

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            throw new InvalidUrlException("URL must not be blank");
        }

        final URI uri;
        try {
            uri = new URI(value);
        } catch (URISyntaxException exception) {
            throw new InvalidUrlException("URL is malformed");
        }

        String scheme = uri.getScheme();
        if (!uri.isAbsolute() || scheme == null
                || !(scheme.toLowerCase(Locale.ROOT).equals("http")
                || scheme.toLowerCase(Locale.ROOT).equals("https"))) {
            throw new InvalidUrlException("URL must be an absolute HTTP or HTTPS URL");
        }
        if (uri.getUserInfo() != null) {
            throw new InvalidUrlException("URL must not contain user information");
        }
        if (uri.getHost() == null || uri.getHost().isBlank()) {
            throw new InvalidUrlException("URL must contain a valid host");
        }
        try {
            uri.getPort();
        } catch (IllegalArgumentException exception) {
            throw new InvalidUrlException("URL contains an invalid port");
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/service/ShortCodeGenerator.java","content":"package com.example.shortener.service;

import org.springframework.stereotype.Component;

import java.security.SecureRandom;

@Component
public class ShortCodeGenerator {

    private static final String ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private static final int CODE_LENGTH = 7;

    private final SecureRandom random = new SecureRandom();

    public String generate() {
        StringBuilder code = new StringBuilder(CODE_LENGTH);
        for (int index = 0; index < CODE_LENGTH; index++) {
            code.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));
        }
        return code.toString();
    }
}
"},{"path":"src/main/java/com/example/shortener/service/LinkPersistenceService.java","content":"package com.example.shortener.service;

import com.example.shortener.model.Link;
import com.example.shortener.repository.LinkRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkPersistenceService {

    private final LinkRepository repository;

    public LinkPersistenceService(LinkRepository repository) {
        this.repository = repository;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public Link saveCandidate(Link link) {
        return repository.saveAndFlush(link);
    }
}
"},{"path":"src/main/java/com/example/shortener/service/LinkService.java","content":"package com.example.shortener.service;

import com.example.shortener.exception.CodeGenerationException;
import com.example.shortener.exception.LinkNotFoundException;
import com.example.shortener.model.Link;
import com.example.shortener.repository.LinkRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkService {

    private static final int MAX_CREATION_ATTEMPTS = 10;

    private final LinkRepository repository;
    private final LinkPersistenceService persistenceService;
    private final UrlValidator urlValidator;
    private final ShortCodeGenerator codeGenerator;

    public LinkService(LinkRepository repository,
                       LinkPersistenceService persistenceService,
                       UrlValidator urlValidator,
                       ShortCodeGenerator codeGenerator) {
        this.repository = repository;
        this.persistenceService = persistenceService;
        this.urlValidator = urlValidator;
        this.codeGenerator = codeGenerator;
    }

    public Link create(String url) {
        urlValidator.validate(url);
        DataIntegrityViolationException lastFailure = null;

        for (int attempt = 0; attempt < MAX_CREATION_ATTEMPTS; attempt++) {
            try {
                return persistenceService.saveCandidate(new Link(codeGenerator.generate(), url));
            } catch (DataIntegrityViolationException exception) {
                lastFailure = exception;
            }
        }

        throw new CodeGenerationException("Unable to generate a unique short code", lastFailure);
    }

    @Transactional(readOnly = true)
    public Link find(String code) {
        return repository.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
    }

    @Transactional
    public String resolveAndCount(String code) {
        Link link = find(code);
        if (repository.incrementClickCount(code) != 1) {
            throw new LinkNotFoundException(code);
        }
        return link.getOriginalUrl();
    }
}
"},{"path":"src/main/java/com/example/shortener/controller/LinkController.java","content":"package com.example.shortener.controller;

import com.example.shortener.api.CreateLinkRequest;
import com.example.shortener.api.LinkResponse;
import com.example.shortener.model.Link;
import com.example.shortener.service.LinkService;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/links")
public class LinkController {

    private final LinkService linkService;

    public LinkController(LinkService linkService) {
        this.linkService = linkService;
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody CreateLinkRequest request,
                                               HttpServletRequest httpRequest) {
        Link link = linkService.create(request.url());
        return ResponseEntity.status(201).body(toResponse(link, httpRequest));
    }

    @GetMapping("/{code}")
    public LinkResponse details(@PathVariable String code, HttpServletRequest httpRequest) {
        return toResponse(linkService.find(code), httpRequest);
    }

    private LinkResponse toResponse(Link link, HttpServletRequest request) {
        return new LinkResponse(link.getCode(), link.getOriginalUrl(), shortUrl(request, link.getCode()),
                link.getClickCount());
    }

    private String shortUrl(HttpServletRequest request, String code) {
        StringBuilder result = new StringBuilder()
                .append(request.getScheme()).append("://").append(request.getServerName());
        int port = request.getServerPort();
        boolean defaultPort = ("http".equalsIgnoreCase(request.getScheme()) && port == 80)
                || ("https".equalsIgnoreCase(request.getScheme()) && port == 443);
        if (!defaultPort) {
            result.append(':').append(port);
        }
        String contextPath = request.getContextPath();
        if (contextPath != null) {
            result.append(contextPath);
        }
        return result.append('/').append(code).toString();
    }
}
"},{"path":"src/main/java/com/example/shortener/controller/RedirectController.java","content":"package com.example.shortener.controller;

import com.example.shortener.service.LinkService;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class RedirectController {

    private final LinkService linkService;

    public RedirectController(LinkService linkService) {
        this.linkService = linkService;
    }

    @GetMapping("/{code:[A-Za-z0-9]{7}}")
    public ResponseEntity<Void> redirect(@PathVariable String code) {
        String destination = linkService.resolveAndCount(code);
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(java.net.URI.create(destination));
        return new ResponseEntity<>(headers, HttpStatus.FOUND);
    }
}
"},{"path":"src/main/java/com/example/shortener/exception/ApiExceptionHandler.java","content":"package com.example.shortener.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.http.converter.HttpMessageNotReadableException;

@RestControllerAdvice
public class ApiExceptionHandler {

    @ExceptionHandler(InvalidUrlException.class)
    public ProblemDetail invalidUrl(InvalidUrlException exception) {
        return problem(HttpStatus.BAD_REQUEST, exception.getMessage());
    }

    @ExceptionHandler({MethodArgumentNotValidException.class, HttpMessageNotReadableException.class})
    public ProblemDetail invalidRequest(Exception exception) {
        String message = "Request body must contain a valid non-blank URL";
        if (exception instanceof MethodArgumentNotValidException validation
                && validation.getBindingResult().getFieldError() != null) {
            message = validation.getBindingResult().getFieldError().getDefaultMessage();
        }
        return problem(HttpStatus.BAD_REQUEST, message);
    }

    @ExceptionHandler(LinkNotFoundException.class)
    public ProblemDetail notFound(LinkNotFoundException exception) {
        return problem(HttpStatus.NOT_FOUND, exception.getMessage());
    }

    @ExceptionHandler(CodeGenerationException.class)
    public ProblemDetail generationFailure(CodeGenerationException exception) {
        return problem(HttpStatus.INTERNAL_SERVER_ERROR, exception.getMessage());
    }

    private ProblemDetail problem(HttpStatus status, String message) {
        ProblemDetail detail = ProblemDetail.forStatusAndDetail(status, message);
        detail.setProperty("error", message);
        return detail;
    }
}
"}],"deletes":[],"summary":"Implemented the persisted JPA URL shortener with validated creation, secure seven-character codes, collision retries, atomic concurrent click counting, metadata APIs, redirects, and ProblemDetail error handling.","decisions":[{"title":"Use a separate REQUIRES_NEW persistence service for code collisions","rationale":"Each candidate insert can roll back independently when the database unique constraint detects a collision, allowing subsequent retries to proceed safely.","alternatives":["Rely on application-side code checks only","Use one transaction for all retry attempts"]},{"title":"Use an atomic JPQL increment for clicks","rationale":"The database performs click_count = click_count + 1, preventing lost updates when redirects arrive concurrently.","alternatives":["Read-modify-write in Java","Synchronize requests in the application process"]},{"title":"Derive short URLs from the incoming servlet request","rationale":"This follows the approved contract without introducing a separate public-base URL configuration.","alternatives":["Use a configured public base URL","Return only the short code"]},{"title":"Constrain redirect routes to seven alphanumeric characters","rationale":"Valid generated codes are exactly seven URL-safe characters, and the constraint prevents malformed paths from being treated as redirects.","alternatives":["Accept any path variable and validate in the service","Use a broader wildcard route"]}]}

{
  "summary": "The implementation generally enforces HTTP(S)-only destinations, uses cryptographically secure seven-character codes, persists links with a uniqueness constraint, and atomically increments click counts. Medium-risk issues remain around unbounded request sizes, host-header-derived URLs, intentional open-redirect behavior, and absent rate limiting.",
  "findings": [
    {
      "severity": "MEDIUM",
      "file": "src/main/java/com/example/shortener/api/CreateLinkRequest.java",
      "issue": "The submitted URL has no maximum length validation. A very large JSON request or URL can consume excessive resources, and URLs longer than the Link.originalUrl database column limit of 2048 characters can reach persistence and produce an internal server error instead of a clear client validation error.",
      "recommendation": "Add an explicit maximum length constraint such as @Size(max = 2048) to the request field, validate the limit before persistence, and configure an appropriate HTTP request-body size limit."
    },
    {
      "severity": "LOW",
      "file": "src/main/java/com/example/shortener/controller/LinkController.java",
      "issue": "The generated shortUrl is constructed from request.getServerName(), scheme, and port. In deployments where the Host header is not validated by a trusted reverse proxy, an attacker can submit a request with an arbitrary Host header and receive a poisoned short URL in the API response, enabling phishing or incorrect link sharing.",
      "recommendation": "Use a configured trusted public base URL, or ensure host and forwarded-header handling is restricted to trusted proxy values and validated against an allow-list."
    },
    {
      "severity": "MEDIUM",
      "file": "src/main/java/com/example/shortener/controller/RedirectController.java",
      "issue": "The service intentionally redirects visitors to any client-supplied valid HTTP(S) destination. This is an open-redirect capability that can be abused for phishing, reputation abuse, or deceptive links. The implementation does not perform destination allow-listing or abuse controls.",
      "recommendation": "If arbitrary destinations are not required, restrict destinations with an allow-list or organizational policy. Otherwise add abuse reporting, reputation screening, or an interstitial warning before redirecting. This behavior is inherent to the requested URL-shortener functionality."
    },
    {
      "severity": "MEDIUM",
      "file": "src/main/java/com/example/shortener/controller/LinkController.java",
      "issue": "There is no rate limiting or abuse protection on link creation, redirect requests, or link-details lookups. Although seven-character SecureRandom codes are difficult to guess, an attacker can still automate resource creation, click inflation, and repeated code attempts.",
      "recommendation": "Add per-client and/or global rate limits, request quotas, and monitoring for creation, redirect, and lookup endpoints. Rate limiting and abuse detection were explicitly out of scope and are therefore an accepted risk for this release."
    }
  ],
  "decisions": [
    {
      "title": "Do not report SecureRandom code generation as a vulnerability",
      "rationale": "ShortCodeGenerator uses SecureRandom with a 62-character alphabet and exactly seven characters, and Link.code has a database uniqueness constraint with collision retries.",
      "alternatives": [
        "Require a longer code or a different token format; this is unnecessary for the stated approximately seven-character requirement.",
        "Report enumeration as blocking; the available code space is large and the implementation uses a cryptographically strong generator."
      ]
    },
    {
      "title": "Classify missing rate limiting as MEDIUM accepted risk",
      "rationale": "The requirements explicitly place rate limiting and abuse detection out of scope, so the risk is listed for audit visibility but should not block this release.",
      "alternatives": [
        "Omit the finding because it is out of scope.",
        "Treat it as HIGH because automated abuse is possible."
      ]
    },
    {
      "title": "Treat arbitrary HTTP(S) redirection as a MEDIUM open-redirect risk",
      "rationale": "Redirecting to the submitted destination is a core functional requirement, but it still creates an abuseable open-redirect capability.",
      "alternatives": [
        "Omit the finding as intentional functionality.",
        "Require destination allow-listing, which would conflict with accepting arbitrary valid HTTP(S) URLs."
      ]
    },
    {
      "title": "Treat request-size handling as a separate finding from URL scheme validation",
      "rationale": "Scheme validation is present and correctly rejects non-HTTP(S) schemes, while input-size enforcement is absent and can cause resource exhaustion or persistence failures.",
      "alternatives": [
        "Report only the database column overflow behavior.",
        "Report only generic HTTP request-body exhaustion."
      ]
    }
  ]
