import com.example.shortener.exception.InvalidUrlException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class UrlValidatorTest {

    private final UrlValidator validator = new UrlValidator();

    @Test
    void acceptsAbsoluteHttpAndHttpsUrlsWithComponents() {
        assertThatCode(() -> validator.validate("https://example.com:8443/path?a=1#fragment"))
                .doesNotThrowAnyException();
        assertThatCode(() -> validator.validate("HTTP://example.com/path"))
                .doesNotThrowAnyException();
    }

    @ParameterizedTest
    @NullAndEmptySource
    @ValueSource(strings = {"   ", "example.com/path", "/relative", "ftp://example.com/file",
            "mailto:user@example.com", "https:///missing-host", "https://user:password@example.com/path",
            "https://example.com/path with spaces", "https://:8080", "https://?query"})
    void rejectsMissingRelativeMalformedUnsupportedAndUserInfoUrls(String value) {
        assertThatThrownBy(() -> validator.validate(value))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageNotBlank();
    }
}
"},{"path":"src/test/java/com/example/shortener/service/ShortCodeGeneratorTest.java","content":"package com.example.shortener.service;

import org.junit.jupiter.api.RepeatedTest;

import java.util.HashSet;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;

class ShortCodeGeneratorTest {

    private final ShortCodeGenerator generator = new ShortCodeGenerator();

    @RepeatedTest(20)
    void generatesSevenUrlSafeCharacters() {
        String code = generator.generate();

        assertThat(code).hasSize(7).matches("[A-Za-z0-9]{7}");
    }

    @org.junit.jupiter.api.Test
    void repeatedGenerationProducesMultipleCodes() {
        Set<String> codes = new HashSet<>();
        for (int i = 0; i < 100; i++) {
            codes.add(generator.generate());
        }

        assertThat(codes).hasSizeGreaterThan(1);
    }
}
"},{"path":"src/test/java/com/example/shortener/service/LinkServiceTest.java","content":"package com.example.shortener.service;

import com.example.shortener.exception.CodeGenerationException;
import com.example.shortener.model.Link;
import com.example.shortener.repository.LinkRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository repository;
    @Mock
    private LinkPersistenceService persistenceService;
    @Mock
    private UrlValidator urlValidator;
    @Mock
    private ShortCodeGenerator codeGenerator;

    @InjectMocks
    private LinkService service;

    @Test
    void retriesAfterCodeCollisionAndPersistsTheNextCandidate() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        Link persisted = new Link("BBBBBBB", "https://example.com");
        when(persistenceService.saveCandidate(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"))
                .thenReturn(persisted);

        Link result = service.create("https://example.com");

        assertThat(result).isSameAs(persisted);
        verify(urlValidator).validate("https://example.com");
        verify(persistenceService, times(2)).saveCandidate(any(Link.class));
        verify(codeGenerator, times(2)).generate();
    }

    @Test
    void reportsControlledFailureWhenCollisionRetryBudgetIsExhausted() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA");
        when(persistenceService.saveCandidate(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"));

        assertThatThrownBy(() -> service.create("https://example.com"))
                .isInstanceOf(CodeGenerationException.class)
