                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(org.hamcrest.Matchers.matchesPattern("[A-Za-z0-9]{7}")))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.endsWith("/")))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();

        String code = json(result, "code");
        assertThat(json(result, "shortUrl")).endsWith("/" + code);
    }

    @Test
    void permitsDuplicateOriginalUrlsAndBothCodesAreRetrievable() throws Exception {
        String url = "https://example.com/duplicate-" + System.nanoTime();
        String first = create(url);
        String second = create(url);

        assertThat(first).isNotEqualTo(second);
        mockMvc.perform(get("/api/links/{code}", first))
                .andExpect(status().isOk()).andExpect(jsonPath("$.url").value(url));
        mockMvc.perform(get("/api/links/{code}", second))
                .andExpect(status().isOk()).andExpect(jsonPath("$.url").value(url));
    }

    @Test
