        mockMvc.perform(get("/api/links/{code}", "ZZZZZZZ"))
                .andExpect(status().isNotFound()).andExpect(jsonPath("$.error").isNotEmpty());
        mockMvc.perform(get("/ZZZZZZZ"))
                .andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"));
    }

    @Test
    void concurrentRedirectsDoNotLoseClickIncrements() throws Exception {
        String code = create("https://example.com/concurrent-" + System.nanoTime());
        int requests = 20;
        ExecutorService executor = Executors.newFixedThreadPool(8);
        try {
            List<Future<MvcResult>> futures = new ArrayList<>();
            for (int i = 0; i < requests; i++) {
                futures.add(executor.submit(() -> mockMvc.perform(get("/" + code)).andReturn()));
            }
            for (Future<MvcResult> future : futures) {
                assertThat(future.get().getResponse().getStatus()).isEqualTo(302);
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk()).andExpect(jsonPath("$.clickCount").value(requests));
    }

    @Test
    void malformedRedirectPathReturnsNotFoundWithoutRedirect() throws Exception {
        mockMvc.perform(get("/too-short"))
                .andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"));
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn();
        return json(result, "code");
    }

    private String json(MvcResult result, String field) throws Exception {
        String content = result.getResponse().getContentAsString();
        int start = content.indexOf("\"" + field + "\":\"") + field.length() + 4;
        int end = content.indexOf('"', start);
        return content.substring(start, end);
    }
}
