{"files":[{"path":"src/test/java/com/example/shortener/LinkShortenerIntegrationTest.java","content":"package com.example.shortener;

import com.example.shortener.model.Link;
import com.example.shortener.repository.LinkRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LinkShortenerIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private LinkRepository linkRepository;

    @Test
    void createsValidLinkWithSevenCharacterCodeAndInitialZeroCount() throws Exception {
        String url = "https://example.com/path?a=1";

        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(org.hamcrest.Matchers.matchesPattern("[A-Za-z0-9]{7}")))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.matchesPattern("http://localhost(:[0-9]+)?/[A-Za-z0-9]{7}")))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();

        String code = json(result, "code");
        assertThat(json(result, "shortUrl")).endsWith("/" + code);
    }

    @Test
    void permitsDuplicateOriginalUrlsAndBothCodesAreRetrievable() throws Exception {
        String url = "https://example.com/duplicate-" + System.nanoTime();
        String first = create(url);
        String second = create(url);

        assertThat(first).isNotEqualTo(second);
        mockMvc.perform(get("/api/links/{code}", first))
                .andExpect(status().isOk()).andExpect(jsonPath("$.url").value(url));
        mockMvc.perform(get("/api/links/{code}", second))
                .andExpect(status().isOk()).andExpect(jsonPath("$.url").value(url));
    }

    @Test
    void persistedCodesAreUniqueAcrossManyCreations() throws Exception {
        List<String> codes = new ArrayList<>();
        for (int i = 0; i < 25; i++) {
            codes.add(create("https://example.com/unique-" + System.nanoTime() + "-" + i));
        }

        assertThat(codes).allMatch(code -> code.matches("[A-Za-z0-9]{7}"));
        assertThat(codes).doesNotHaveDuplicates();
        assertThat(linkRepository.findAll()).extracting(Link::getCode).containsAll(codes);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "   ", "relative/path", "ftp://example.com/file",
            "not a url", "https://user:pass@example.com/private", "https:///missing-host"})
    void rejectsInvalidUrlsWithProblemDetailAndDoesNotCreateThatUrl(String invalidUrl) throws Exception {
        long before = linkRepository.count();
        String body = "{\"url\":\"" + invalidUrl + "\"}";

        mockMvc.perform(post("/api/links").contentType("application/json").content(body))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.error").isString())
                .andExpect(jsonPath("$.error").value(org.hamcrest.Matchers.not(org.hamcrest.Matchers.blankOrNullString())));
        assertThat(linkRepository.count()).isEqualTo(before);
    }

    @Test
    void rejectsMissingUrlBodyWithBadRequestProblemDetail() throws Exception {
        mockMvc.perform(post("/api/links").contentType("application/json").content("{}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.error").isNotEmpty());
    }

    @Test
    void rejectsMalformedJsonBodyWithBadRequestProblemDetail() throws Exception {
        mockMvc.perform(post("/api/links").contentType("application/json").content("{\"url\":"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.error").isString())
                .andExpect(jsonPath("$.error").value(org.hamcrest.Matchers.not(org.hamcrest.Matchers.blankOrNullString())));
    }

    @Test
    void redirectsKnownCodeAndIncrementsExactlyOnce() throws Exception {
        String url = "https://example.com/redirect-" + System.nanoTime();
        String code = create(url);

        mockMvc.perform(get("/" + code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.clickCount").value(1));
    }

    @Test
    void detailsLookupIsReadOnlyAndUnknownCodesReturnNotFound() throws Exception {
        String code = create("https://example.com/details-" + System.nanoTime());
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk()).andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/{code}", "ZZZZZZZ"))
                .andExpect(status().isNotFound()).andExpect(jsonPath("$.error").isNotEmpty());
        mockMvc.perform(get("/ZZZZZZZ"))
                .andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"));
    }

    @Test
    void concurrentRedirectsDoNotLoseClickIncrements() throws Exception {
        String code = create("https://example.com/concurrent-" + System.nanoTime());
        int requests = 20;
        ExecutorService executor = Executors.newFixedThreadPool(8);
        try {
            List<Future<MvcResult>> futures = new ArrayList<>();
            for (int i = 0; i < requests; i++) {
                futures.add(executor.submit(() -> mockMvc.perform(get("/" + code)).andReturn()));
            }
            for (Future<MvcResult> future : futures) {
                assertThat(future.get().getResponse().getStatus()).isEqualTo(302);
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk()).andExpect(jsonPath("$.clickCount").value(requests));
    }

    @Test
    void malformedRedirectPathReturnsNotFoundWithoutRedirect() throws Exception {
        mockMvc.perform(get("/too-short"))
                .andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"));
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn();
        return json(result, "code");
    }

    private String json(MvcResult result, String field) throws Exception {
        String content = result.getResponse().getContentAsString();
        int start = content.indexOf("\"" + field + "\":\"") + field.length() + 4;
        int end = content.indexOf('"', start);
        return content.substring(start, end);
    }
}
