import com.example.shortener.exception.InvalidUrlException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class UrlValidatorTest {

    private final UrlValidator validator = new UrlValidator();

    @Test
    void acceptsAbsoluteHttpAndHttpsUrlsWithComponents() {
        assertThatCode(() -> validator.validate("https://example.com:8443/path?a=1#fragment"))
                .doesNotThrowAnyException();
        assertThatCode(() -> validator.validate("HTTP://example.com/path"))
                .doesNotThrowAnyException();
    }

    @ParameterizedTest
    @NullAndEmptySource
    @ValueSource(strings = {"   ", "example.com/path", "/relative", "ftp://example.com/file",
            "mailto:user@example.com", "https:///missing-host", "https://user:password@example.com/path",
            "https://example.com/path with spaces", "https://:8080", "https://?query"})
    void rejectsMissingRelativeMalformedUnsupportedAndUserInfoUrls(String value) {
        assertThatThrownBy(() -> validator.validate(value))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageSatisfying(message -> assertThat(message).isNotBlank());
    }
}
